from review64 import *
def artifacts(exclusions=()):return [rawpin(p) for p in sorted(OUT.rglob('*')) if p.is_file() and p.relative_to(OUT).as_posix() not in exclusions]
def check(rows):
 for row in rows:assert rawpin(Path(row['path']))==row,('changed output',row['path'])
def prepare():
 assert git('rev-parse','HEAD')==COMMIT
 f=load(OUT/'focused/receipt.json');assert f['exit_code']==0 and f['terminal_closed'] and f['pre_post_equal'];check(f['post'])
 m=load(OUT/'mathematical-review.json');assert m['status']=='MATHEMATICS_ACCEPTED_PRECOMMIT_PUBLICATION_BLOCKED'
 manifest=load(ROOT/'lake-manifest.json');expected=next(p['rev'] for p in manifest['packages'] if p['name']=='mathlib');assert git('-C','.lake/packages/mathlib','rev-parse','HEAD')==expected==load(OUT/'input.manifest.json')['Mathlib_HEAD']
 sm=load(OUT/'input.supplement.json');maps={v['map']['original']['path']:v for v in sm['qualified_maps']}
 for row in load(OUT/'input.manifest.json')['inputs']:
  p=Path(row['path']);assert sha(Path(row['exact_RAW_snapshot']).read_bytes())==row['raw_sha256']
  if sha(p.read_bytes())!=row['raw_sha256']:assert rawpin(p)==maps[p.as_posix()]['current']
 for row in load(OUT/'late-inspection.inputs.json')['inputs']:assert rawpin(Path(row['path']))==row
 write('verdict.json',{'schema_version':1,'actor':ACTOR,'actual_preparer_pid':os.getpid(),'review_kind':'INDEPENDENT_PRECOMMIT_MATHEMATICAL_REVIEW','checked_BASE':COMMIT,'exact_SCI64_commit':'DOES_NOT_EXIST_AT_THIS_REVIEW','candidate_uncommitted':True,'mathematics':'ACCEPTED','publication':'BLOCKED_EXCERPT_BODY_BINDING_STEP6','VERIFIED_transition':False,'accepted_delta':m['proof_stages'],'candidate_source_pins':[x['candidate'] for x in m['candidate_headers_exact_sealed']],'compiler_receipt':rawpin(OUT/'focused/receipt.json'),'proof_review':rawpin(OUT/'mathematical-review.json'),'blocker':m['presentation_blockers'],'body_repair_proposal':rawpin(OUT/'step6.BODY-repair.proposal.json'),'remaining_boundary':m['remaining_boundary'],'source_blind_decoder_and_anti_anchored_source_review':'Separate independently running admission; no source/self-verification credit here.','source_Lean_graph_distinction':'Generic square order/rough gradient/Poincare/macro63 are genuine compiled ingredients. Reader Source Proof Graph remains a source reconstruction, not import topology or scanner edge proof.','conceptual_mirror_audit':'none-found independently consistent with within-model compiled adapters and reused coercivity mechanism; no new weaker transport bridge discovered.','authorization':'Only independent-math64 writes; no canonical/shared/Git/ledger/CLOSED63 modification.'})
 excluded=['run.json','named-mathematics.payload.json','native.receipt.json','output.manifest.json','lease.json','proposed-lease.closed.json','finalizer/stdout.log','finalizer/stderr.log','finalizer/receipt.json','readback/stdout.log','readback/stderr.log','readback/receipt.json']
 evidence=artifacts(excluded);payload=write('named-mathematics.payload.json',{'kind':'COMPLETE_NAMED_INDEPENDENT_PRECOMMIT_MATHEMATICS64_RAW_PAYLOAD','actor':ACTOR,'checked_BASE':COMMIT,'candidate_uncommitted':True,'full_mathematical_review':m,'full_native_verdict':load(OUT/'verdict.json'),'complete_owned_pre_finalization_evidence':evidence,'source_admission_and_exact_commit_VERIFIED':False,'closure_layers':'Whole run and output manifest then final CLOSED_LAST lease bind all self/finalizer/readback layers; final read-only terminal reports lease RAW.'})
 run={'schema_version':1,'kind':'INDEPENDENT_PRECOMMIT_MATHEMATICAL_REVIEW64_NATIVE_RUN','actor':ACTOR,'actual_finalizer_pid':os.getpid(),'checked_BASE':COMMIT,'candidate_uncommitted':True,'exact_SCI64_commit_review':False,'VERIFIED_transition':False,'whole_input_manifest':rawpin(OUT/'input.manifest.json'),'qualified_finite_metadata_supplement':rawpin(OUT/'input.supplement.json'),'complete_named_mathematics_RAW_payload':rawpin(payload),'distinct_complete_named_RAW_payload_sha256':sha(payload.read_bytes()),'all_owned_pre_finalization_artifacts':evidence,'whole_run_hash_recipe':'SHA256 UTF8 sorted compact logical whole run JSON, removing ONLY top-level run_sha256; no other field removed.','named_payload_hash_recipe':'SHA256 COMPLETE RAW named-mathematics.payload.json bytes with no deletion and no reserialization.','self_layer_exclusions':excluded,'closure_rule':'output.manifest binds completed run/receipt/payload; final CLOSED_LAST lease binds output manifest and all finalizer/readback/files except only lease itself. Actual postclose read-only terminal reports lease RAW.','mathematical_verdict':'ACCEPTED_UNCOMMITTED_CANDIDATE','publication_verdict':'BLOCKED_STEP6_RAW_BODY_EXCERPT','remaining_boundary':m['remaining_boundary']}
 run['run_sha256']=sha(compact(run));rp=write('run.json',run)
 nr=write('native.receipt.json',{'status':'MATH_ACCEPTED_PRECOMMIT_PUBLICATION_BLOCKED','actor':ACTOR,'actual_finalizer_pid':os.getpid(),'checked_BASE':COMMIT,'candidate_uncommitted':True,'whole_logical_run_sha256':run['run_sha256'],'run_RAW':rawpin(rp),'distinct_complete_named_RAW_payload_sha256':sha(payload.read_bytes()),'complete_named_payload_RAW':rawpin(payload),'verdict':rawpin(OUT/'verdict.json'),'independent_compiler_pid':f['actual_foreground_pid'],'independent_compiler_exit_code':f['exit_code'],'closure_state_authority':'Final lease.json CLOSED_LAST','exact_SCI64_VERIFIED':False})
 omit=['output.manifest.json','lease.json','proposed-lease.closed.json','finalizer/stdout.log','finalizer/stderr.log','finalizer/receipt.json','readback/stdout.log','readback/stderr.log','readback/receipt.json']
 om=write('output.manifest.json',{'status':'COMPLETED_PRE_CLOSURE_OUTPUT_BINDINGS','artifacts':artifacts(omit),'layer_exclusions':omit,'final_coverage':'Final CLOSED_LAST lease includes every owned file except itself; lease RAW provided by postclose read-only terminal.'})
 write('proposed-lease.closed.json',{'status':'CLOSED_LAST','actor':ACTOR,'checked_BASE':COMMIT,'candidate_uncommitted':True,'whole_logical_run_sha256':run['run_sha256'],'distinct_complete_named_RAW_payload_sha256':sha(payload.read_bytes()),'native_receipt':rawpin(nr),'output_manifest':rawpin(om),'mathematics':'ACCEPTED_PRECOMMIT','publication':'BLOCKED_STEP6_RAW_BODY_EXCERPT','VERIFIED_transition':False,'final_write_rule':'close validates actual foreground terminal finalizer/readback receipts then writes ONLY lease.json as final owned mutation; subsequent Python-B postclose is read-only.','self_layer_exclusions':['lease.json'],'closure_exit_evidence':'Actual foreground closure and read-only postclose terminal tool outputs, reported to parent; no owned postclose log write.'})
 print(json.dumps({'status':'PREPARED','actual_pid':os.getpid(),'whole_logical_run_sha256':run['run_sha256'],'distinct_complete_named_RAW_payload_sha256':sha(payload.read_bytes())}))
def readback():
 r=load(OUT/'run.json');c=dict(r);c.pop('run_sha256');assert sha(compact(c))==r['run_sha256'];assert sha((OUT/'named-mathematics.payload.json').read_bytes())==r['distinct_complete_named_RAW_payload_sha256'];check(load(OUT/'output.manifest.json')['artifacts']);assert git('rev-parse','HEAD')==COMMIT
 print(json.dumps({'status':'READ_ONLY_CANDIDATE_BINDINGS_PASS','actual_pid':os.getpid(),'checked_BASE':COMMIT,'whole_logical_run_sha256':r['run_sha256'],'distinct_complete_named_RAW_payload_sha256':r['distinct_complete_named_RAW_payload_sha256']}))
def close():
 readback()
 for name in ['finalizer/receipt.json','readback/receipt.json']:
  p=load(OUT/name);assert p['exit_code']==0 and p['terminal_closed']
 l=load(OUT/'proposed-lease.closed.json');l['actual_finalizer']=rawpin(OUT/'finalizer/receipt.json');l['actual_readback']=rawpin(OUT/'readback/receipt.json');l['actual_final_closure_pid']=os.getpid();l['complete_owned_output_manifest_after_readback']=artifacts(['lease.json']);print(json.dumps({'status':'CLOSED_LAST_FINAL_OWNED_WRITE_NOW','actual_pid':os.getpid(),'owned_files_bound_excluding_lease':len(l['complete_owned_output_manifest_after_readback'])}));sys.stdout.flush();write('lease.json',l)
def readonly():
 l=load(OUT/'lease.json');assert l['status']=='CLOSED_LAST';check(l['complete_owned_output_manifest_after_readback']);assert {x['path'] for x in l['complete_owned_output_manifest_after_readback']}=={p.as_posix() for p in OUT.rglob('*') if p.is_file() and p.name!='lease.json'};readback();print(json.dumps({'status':'READ_ONLY_POSTCLOSE_PASS','actual_pid':os.getpid(),'lease_RAW_sha256':sha((OUT/'lease.json').read_bytes()),'owned_file_count':len(l['complete_owned_output_manifest_after_readback'])+1,'no_writes_after_CLOSED_LAST':True}))
if __name__=='__main__':{'prepare':prepare,'readback':readback,'close':close,'readonly':readonly}[sys.argv[1]]()
